// model/mpv.mjs -- the mpv argv, the player verbs, and audio and subtitle tracks. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  ELLIPSIS, SEP, MPV_RESERVED, MPV_DEMUXER_TLS_WORDS, MPV_TLS_VERIFY,
  MPV_PIN_BLOCK, MPV_GPU_SW
} from "./build.mjs"
import {
  str, asList
} from "./text.mjs"
import {
  cleanName
} from "./channels.mjs"
import {
  PIP_CLASS
} from "./pip.mjs"
import {
  redactUrls, scrubUrls
} from "./privacy.mjs"

// ------------------------------------------------------------ mpv

// Options that are allowed through but hand the stream address to a SECOND
// program (PO-10, D-PLY-5). None of these is reserved and none is refused:
// PO-5 keeps `--ytdl` available on purpose, because it is the documented way
// to play a link that is not a direct stream. What the plugin owes the user
// is that the cost is said out loud at the moment the option is in force,
// not once in a README they read when they installed it.
//
// With `--ytdl=yes`, mpv's builtin `ytdl_hook` runs `yt-dlp ... -- <URL>` on
// every open, putting the full credentialed URL on another process's 0444
// command line for seconds (measured in QA-RESULTS M8 / D-PLY-5). The
// `--ytdl-*` options exist only to configure that handoff, and `--script-opts`
// reaches the same hook - `ytdl_hook-ytdl_path` even chooses which program
// receives the address. `--script` / `--scripts` are reserved, so mpv's own
// builtin scripts are the only ones these options can reach.
//
// Mirrored by `mpv_arg_warnings()` in the helper (bin/helper/) and pinned by the
// `mpvHandoff` vectors in the player-argv.json. fixture (dev branch)
// D-SINK-51 (2026-10-29): `--http-proxy` joins them. For a plain-http stream
// the proxy receives the request line -- the WHOLE credentialed URL -- and the
// provider headers (measured: the proxy logged both); for https it receives
// the host name only. A real need for some users, so warned, not refused.
var MPV_HANDOFF = {
  "--ytdl-format": true,
  "--ytdl-raw-options": true,
  "--http-proxy": true
}
// The same hook, reached through a script option: warned on only when the
// value actually names it, so `--script-opts=osc-scalewindowed=2` is silent.
var MPV_HANDOFF_SCRIPT_OPTS = { "--script-opts": true, "--script-opt": true }
// `--ytdl` is a flag: only a value that turns it ON is a handoff, so a user
// who writes the default out in full (`--ytdl=no`) is never warned at all.
var MPV_YTDL_OFF = { "no": true, "0": true, "false": true }
var MPV_HANDOFF_TEXT = " hands the stream address to another program"
// M5-01 (design 2.6): the same PO-10 mechanism, a different cost.
// `--cache-on-disk` writes the stream to the user's own disk continuously
// (1.8 to 4.5 GiB per hour at the measured bitrates, into a file mpv unlinks
// at creation, so `ls` and `du` show nothing). Allowed, because it is the
// user's disk; said out loud, because nothing else would say it. Mirrored
// by `mpv_arg_writes_disk()` in the helper (bin/helper/), same fixture.
var MPV_DISK_WARN = { "--cache-on-disk": true }
var MPV_DISK_TEXT = " writes the stream to disk while it plays"

// mpv spells the list-option variants `--opt-append`, `--opt-set` and so on;
// every one of them sets the same option, so the base name is what decides.
function mpvOptionBase(name) {
  return str(name).replace(/-(add|append|set|pre|clr|del|remove|toggle)$/, "")
}

// "" when the token is harmless, else the option NAME to name in the warning.
// The value is never returned: it can itself carry a credentialed URL (a
// proxy in `--ytdl-raw-options`, say) and a warning line is a sink (R12).
function mpvHandoffName(token) {
  var text = str(token)
  var eq = text.indexOf("=")
  var name = eq === -1 ? text : text.substring(0, eq)
  var value = eq === -1 ? "" : text.substring(eq + 1)
  // `--no-ytdl` turns the handoff off; there is nothing to warn about.
  if (name.indexOf("--no-") === 0) return ""
  var base = mpvOptionBase(name)
  if (base === "--ytdl") return MPV_YTDL_OFF[value.toLowerCase()] === true ? "" : name
  if (MPV_HANDOFF[base] === true) return name
  if (MPV_HANDOFF_SCRIPT_OPTS[base] === true) return value.indexOf("ytdl") === -1 ? "" : name
  return ""
}

// The option NAME when the token turns the disk cache on, "" otherwise. A
// flag like `--ytdl`: `--no-cache-on-disk` and `=no` turn it off, silently.
function mpvDiskName(token) {
  var text = str(token)
  var eq = text.indexOf("=")
  var name = eq === -1 ? text : text.substring(0, eq)
  var value = eq === -1 ? "" : text.substring(eq + 1)
  if (name.indexOf("--no-") === 0) return ""
  if (MPV_DISK_WARN[mpvOptionBase(name)] !== true) return ""
  return MPV_YTDL_OFF[value.toLowerCase()] === true ? "" : name
}

// The whole warning line for one token, or "". Each cost carries its own
// sentence, so the user is told WHAT the option does.
function mpvArgWarning(token) {
  var name = mpvHandoffName(token)
  if (name !== "") return "mpvArg " + name + MPV_HANDOFF_TEXT
  name = mpvDiskName(token)
  if (name !== "") return "mpvArg " + name + MPV_DISK_TEXT
  return ""
}

// One line per distinct option, in the order the user wrote them.
function mpvArgWarnings(tokens) {
  var list = asList(tokens)
  var seen = {}
  var out = []
  for (var i = 0; i < list.length; i++) {
    var line = mpvArgWarning(list[i])
    if (line === "" || seen[line] === true) continue
    seen[line] = true
    out.push(line)
  }
  return out
}

// F-UX-7 (2026-10-24). A refused token used to be written to the journal
// (mpvRejectedLine, below) and shown to the user nowhere: the footer's
// warning list was built from KEPT tokens only, so a pasted `--tls-verify=no`
// or `--no-load-scripts` looked like it did nothing, and the README had to
// say "look in the shell's log". So `warnings` now carries one line per
// distinct refused option too, by its NAME alone -- the footer is a sink
// under rule 5 and a refused token is exactly where a credential goes
// (`--stream-lavf-o=http_proxy=http://u:pw@p`, D-SINK-24) -- through the
// same mpvRejectedName the journal line uses: the text before `=` when it
// is option-shaped, else the fixed word `<token>`. An option-shaped name
// that was refused is reserved (that is the only way splitMpvArgs refuses
// one), so the sentence says so; a `<token>` is not an option at all.
var MPV_REFUSED_TEXT = " refused: reserved by the plugin"
var MPV_REFUSED_JUNK_TEXT = " refused: not a --option"

function mpvRefusedWarning(token) {
  var name = mpvRejectedName(token)
  return "mpvArg " + name + (name === "<token>" ? MPV_REFUSED_JUNK_TEXT : MPV_REFUSED_TEXT)
}

// One line per distinct refused NAME, in the order the user wrote them.
function mpvRefusedWarnings(rejected) {
  var list = asList(rejected)
  var seen = {}
  var out = []
  for (var i = 0; i < list.length; i++) {
    var token = str(list[i])
    if (token === "") continue
    var line = mpvRefusedWarning(token)
    if (seen[line] === true) continue
    seen[line] = true
    out.push(line)
  }
  return out
}

// mpvArgs is one string of whitespace-separated `--key[=value]` tokens.
// Anything else (including reserved options) is rejected, never guessed.
// `warnings` covers the tokens that were REFUSED (since F-UX-7, by name
// only) and then the tokens that are KEPT (what the option does, PO-10); the
// footer shows the list where the kept ones were already shown
// (Service.playerArgWarnings). The refused lines come FIRST because the
// footer's one line (Model.footerWarning -> warningLine) prints the first
// warning and counts the rest as `(+N more)`: with the kept lines first, a
// refused option beside any kept-option warning was named nowhere the user
// looks, and the README said it was (the recheck's P2 on fda0d52).
function splitMpvArgs(text) {
  var args = []
  var rejected = []
  var parts = str(text).split(/\s+/)
  for (var i = 0; i < parts.length; i++) {
    var token = parts[i]
    if (token === "") continue
    var ok = /^--[a-z0-9][a-z0-9-]*(=.*)?$/.test(token)
    var name = token.indexOf("=") === -1 ? token : token.substring(0, token.indexOf("="))
    // The BASE name decides (D-SINK-2): `--scripts-append` sets the same
    // option `--scripts` does, and reserving one spelling reserved nothing.
    var base = mpvOptionBase(name)
    if (!ok || MPV_RESERVED[name] === true || MPV_RESERVED[base] === true
        || name.indexOf("--no-") === 0 && (MPV_RESERVED["--" + name.substring(5)] === true
                                           || MPV_RESERVED[mpvOptionBase("--" + name.substring(5))] === true)
        || demuxerNamesTls(base, token)) rejected.push(token)
    else args.push(token)
  }
  return { args: args, rejected: rejected, warnings: mpvRefusedWarnings(rejected).concat(mpvArgWarnings(args)) }
}

// D-SINK-43: a `--demuxer-lavf-o*` token that names a TLS setting. See
// MPV_DEMUXER_TLS_WORDS (build.mjs) for why a substring and not a parse.
// Mirror of demuxer_names_tls in the helper.
function demuxerNamesTls(base, token) {
  if (base !== "--demuxer-lavf-o") return false
  var text = str(token)
  for (var i = 0; i < MPV_DEMUXER_TLS_WORDS.length; i++) {
    if (text.indexOf(MPV_DEMUXER_TLS_WORDS[i]) !== -1) return true
  }
  return false
}

// D-SINK-24 (ruling R32b). The journal line for the tokens splitMpvArgs
// refused, or "". It printed them WHOLE, and a refused token is exactly where
// a credential goes: `--stream-lavf-o=http_proxy=http://user:pw@proxy:3128`
// (reserved since D-SINK-15), the value half of `--http-proxy http://u:pw@p`
// split off by the whitespace split, a `Bearer eyJ...` or `Basic dXNl...`
// split off a `--http-header-fields=Authorization: ...`, and a scheme-less
// `user:pw@proxy:3128` -- all reached the user journal verbatim on every
// player start and restart. The console is a sink rule 5 names. So a token
// is journaled by its option NAME only: the text before `=` when it starts
// with `--`, else the fixed word `<token>` -- never a value, never a bare
// token. The round-2 line cut at `=` and redacted URLs, which still printed
// a bearer value whole (the recheck's P2): a token that is not an option has
// no name to print, so it gets a placeholder. The helper's own refusal line
// (`dropped mpvArg ...`, 08-player-verbs.py) is the same rule, pinned by
// the player suite on the dev branch. redactUrls still runs over the joined names, a
// second layer for a `--` token that carries `://` without an `=`.
function mpvRejectedLine(rejected) {
  var list = asList(rejected)
  var names = []
  for (var i = 0; i < list.length; i++) {
    var token = str(list[i])
    if (token === "") continue
    names.push(mpvRejectedName(token))
  }
  if (names.length === 0) return ""
  return "omarchy-iptv: ignoring mpvArgs tokens: " + redactUrls(names.join(" "))
}

// R32b' (D-SINK-24, 2026-10-22): what a refused token is journaled as. Its
// NAME, the text before `=`, only when that name is option-shaped,
// `^--[a-z0-9][a-z0-9-]*$` (MPV_ARG_RE's name half); else the fixed word
// `<token>`. R32b printed the name of any `--` token, and a token refused
// BECAUSE its name is not option-shaped is exactly the one whose name can
// carry anything: `--u:pw@h=1` printed `--u:pw@h`. The helper's `dropped
// mpvArg` line is the same rule through its MPV_ARG_RE.
function mpvRejectedName(token) {
  var t = str(token)
  var eq = t.indexOf("=")
  var name = eq === -1 ? t : t.substring(0, eq)
  return /^--[a-z0-9][a-z0-9-]*$/.test(name) ? name : "<token>"
}

// Per-channel HTTP headers as mpv argv items. `-append` list form so header
// values may contain commas without escaping.
function headerArgs(headers) {
  var out = []
  if (!headers || typeof headers !== "object") return out
  for (var name in headers) {
    var value = str(headers[name])
    if (!/^[A-Za-z0-9-]+$/.test(name) || /[\r\n]/.test(value)) continue
    var lower = name.toLowerCase()
    if (lower === "user-agent") out.push("--user-agent=" + value)
    else if (lower === "referer" || lower === "referrer") out.push("--referrer=" + value)
    else out.push("--http-header-fields-append=" + name + ": " + value)
  }
  return out
}

// mpv property-expands `--title` (man mpv: "Properties are expanded"), so a
// playlist entry named "${path}" would put the stream URL, credentials and
// all, into the window title (S-01, R12). "$>" turns expansion off for the
// rest of the string; verified on mpv 0.41 with `expand-text` over IPC:
// "$>${path}" stays literal. `force-media-title` is NOT expanded (verified:
// media-title returned "$>${path}" verbatim), so it carries the plain name;
// a prefix there would show up literally in the OSC and `media-title`.
// The helper's cmd_play applies the same prefix on the IPC path.
var MPV_RAW_PREFIX = "$>"

function mpvWindowTitle(name) {
  return MPV_RAW_PREFIX + str(name)
}

// Where the player is allowed to write (PO-11, D-PLY-7). mpv's own key
// bindings are live on its window and two of them write a durable file: `s`
// takes a screenshot and `Q` (quit-watch-later) writes a resume record.
// Before this they landed wherever the shell happened to be - the user's
// home for the screenshot, mpv's own ~/.local/state/mpv tree for the resume
// record - at mode 0644, outside every list of files this plugin says it
// writes.
//
//  - `cwd` is the runtime directory (0700, already there for the socket), so
//    anything still written relative to the process is private and gone at
//    logout rather than accumulating in $HOME.
//  - `screenshots` is durable on purpose: the user asked for that file, so
//    the runtime directory would be data loss at logout. It sits under the
//    state directory this plugin already owns and documents.
//  - `watchLater` is a resume position for a live stream, never worth
//    keeping: private and ephemeral.
//  - `shaderCache` is D-PLY-10, ruling CL2: without it mpv compiles its
//    shaders into $XDG_CACHE_HOME/mpv/, outside every list of files this
//    plugin says it writes. The cache is content-free and regenerable, so it
//    belongs in the runtime directory - already 0700, already documented,
//    gone at logout - and adds no durable path and nothing to clean up.
//
// Mirrored by `player_dirs()` in the helper (bin/helper/).
function playerDirs(socketPath, stateDir) {
  var runtime = dirnameOf(socketPath)
  return {
    cwd: runtime,
    screenshots: str(stateDir) + "/screenshots",
    watchLater: runtime + "/watch-later",
    shaderCache: runtime + "/shader-cache"
  }
}

// os.path.dirname for the paths this plugin deals in.
function dirnameOf(path) {
  var text = str(path)
  var cut = text.lastIndexOf("/")
  if (cut < 0) return ""
  if (cut === 0) return "/"
  return text.substring(0, cut)
}

// Full argv for the mpv launch (ARCHITECTURE-PLAYER.md section 6). Nothing
// channel-specific is here any more: no URL, no trailing "--", no header
// options and no per-channel title, because all of them travel over the 0600
// socket instead (S-03 closed). `--idle=once` is PO-1: mpv idles at startup
// so the first channel arrives by `loadfile` like every later one, and still
// exits when the playlist ends, which keeps today's "the window vanishes on
// a failure" behaviour and the degraded 10 s status-poll fallback.
// The neutral `--title=$>IPTV` / `--force-media-title=IPTV` keep mpv from
// flashing its own "No file - mpv"; the channel title follows over IPC.
// Mirrored by `mpv_launch_argv()` in the helper (bin/helper/), pinned by the shared
// vectors in the player-argv.json. fixture (dev branch)
function buildMpvArgv(params) {
  var p = params || {}
  var dirs = p.dirs || playerDirs(p.socketPath, p.stateDir)
  var argv = [
    "mpv",
    "--input-ipc-server=" + str(p.socketPath),
    // PIP_CLASS, not a third copy of the string. This flag is what makes the
    // window findable, and picture in picture matches `class === PIP_CLASS`
    // to decide which window it may float, shrink, move and pin. Two
    // literals that agree today can disagree tomorrow, and the failure is
    // silent: PiP would simply answer "Cannot find the player window" for
    // ever. The python mirror keeps its own literal and is pinned to this
    // one by the player-argv.json. fixture (dev branch)
    "--wayland-app-id=" + PIP_CLASS,
    "--force-window=immediate",
    "--idle=once",
    "--keep-open=no",
    "--title=" + mpvWindowTitle("IPTV"),
    "--force-media-title=IPTV",
    "--msg-level=all=error",
    // Live streams never need yt-dlp; without this mpv shells out to it on
    // every dead URL (seconds of delay and noise per failed zap). User
    // mpvArgs come later, so `--ytdl=yes` can re-enable it (PO-5).
    "--ytdl=no",
    // D-SINK-4. mpv autoloads every script in its system directory, and on
    // this distribution that includes mpv-mpris, which publishes `xesam:url`
    // -- the stream URL, credentials and all -- to every process on the
    // session bus for as long as a channel plays. Measured on the real bus
    // with a synthetic credential; `--force-media-title` guards the TITLE and
    // there is no equivalent option for the URL.
    //
    // mpv-mpris has no configuration surface at all (no script-opts; it reads
    // `path` and publishes it), so keeping it and not leaking is not
    // available. This plugin loads no script of its own, and `--script` /
    // `--scripts` / `--config-dir` are already reserved, so nothing here
    // depends on autoload.
    //
    // The cost, stated rather than hidden: Omarchy's own media widget reads
    // MPRIS and will stop showing the channel. That display is redundant --
    // this plugin's bar widget already shows the playing channel name -- and
    // a duplicate label is not worth a credential on the bus.
    "--load-scripts=no",
    // PO-11: the two directories mpv's own key bindings write into, named
    // rather than inherited. `--screenshot-dir` is deliberately NOT reserved
    // - user tokens land after these, so anyone who wants their screenshots
    // in ~/Pictures can still say so - while `--watch-later-dir` IS
    // reserved, because a resume record naming a stream path has no business
    // being pointed back at $HOME.
    "--screenshot-dir=" + str(dirs.screenshots),
    "--watch-later-dir=" + str(dirs.watchLater),
    // D-PLY-10 / CL2: mpv's shader and ICC caches default into
    // $XDG_CACHE_HOME/mpv/, outside this plugin's tree. Contained in the
    // runtime directory, ephemeral. Neither option is reserved - both caches
    // are content-free - so user tokens after these can still move them.
    "--gpu-shader-cache-dir=" + str(dirs.shaderCache),
    "--icc-cache-dir=" + str(dirs.shaderCache),
    // D-PLY-27: accept a software renderer (MPV_GPU_SW in build.mjs has the
    // measurement). In the base section, BEFORE the user's tokens, so a
    // `--gpu-sw=no` or `--no-gpu-sw` in extraArgs lands after it and wins:
    // a rendering preference, not a security layer, so unlike MPV_TLS_VERIFY
    // it appears once, is not re-asserted at the tail and is not reserved.
    MPV_GPU_SW,
    // D-SINK-13, LAYER 1: stated here, where a reader of the specification
    // looks to find out what the player is launched with. mpv's own default is
    // `--tls-verify=no` (`mpv --list-options` on 0.41.0), so without this the
    // plugin handed provider headers and an HTTPS stream URL to a peer it
    // never authenticated. Layer 1 alone is NOT the fix - see the return.
    MPV_TLS_VERIFY
  ]
  // D-SINK-13, LAYER 2, and the line that actually guarantees verification.
  //
  // THE TWO OCCURRENCES OF MPV_TLS_VERIFY ARE NOT REDUNDANT. Removing either
  // one is a security change, not a tidy-up, and the one below is the one that
  // holds:
  //
  //  - mpv resolves a repeated option by taking the LAST token on the command
  //    line. User mpvArgs land between the base argv and this line, so
  //    whatever a user writes is overridden here rather than overriding us.
  //  - That matters because `--tls-verify` is not the only way to turn
  //    verification off. `--profile=NAME` applies every option in that profile
  //    at the point the token appears, and a profile in the user's own
  //    mpv.conf can set `tls-verify=no`. The lead measured it on 2026-10-07:
  //    with layer 1 only, `--profile=evil` naming such a profile PLAYED a
  //    self-signed stream (exit 0); with this trailing token the same command
  //    refused it (exit 2, "Peer certificate failed verification"). The same
  //    measurement refused `--tls-verify=no` and `--no-tls-verify` behind it.
  //  - So this layer covers the indirections nobody has enumerated, which is
  //    why `--profile` is deliberately not on MPV_RESERVED.
  //  - It cannot be escaped by a bare `--` (which would make the rest
  //    filenames): splitMpvArgs cannot emit one, because the token pattern
  //    requires `--` followed by a lowercase letter or digit.
  //  - And it does not break the escape hatch: `--tls-ca-file` is unreserved,
  //    rides in extraArgs, and names a CA for THIS token to verify against.
  //    Measured playing a private-CA stream with the trailing token in place.
  //
  // Mirrored by mpv_launch_argv() in the helper (bin/helper/) and pinned there by the
  // `--profile=evil` vector in the player-argv.json fixture (dev branch),
  // whose user arguments are what make this line visible at all.
  //
  // D-SINK-43..46 (owner, 2026-10-29) widened the tail from one token to the
  // pin block, on the same reasoning: every option a security layer depends
  // on is re-asserted after the user's tokens, so the last word is ours over a
  // token, a named profile and a plain mpv.conf line, and each is set from the
  // command line, so no per-file profile replaces it. The block ends with
  // MPV_TLS_VERIFY, so everything above still describes the last element.
  return argv.concat(asList(p.extraArgs)).concat(mpvPinBlock(dirs))
}

// The trailing pins: the contained resume folder first (a named profile in
// the user's own mpv.conf moved it: measured), then MPV_PIN_BLOCK. Mirror of
// mpv_pin_block() in the helper.
function mpvPinBlock(dirs) {
  var d = dirs || {}
  return ["--watch-later-dir=" + str(d.watchLater)].concat(MPV_PIN_BLOCK)
}

// ------------------------------------------------------------ player verbs
//
// argv for the helper's `player` verb group (ARCHITECTURE-PLAYER.md 4.3).
// These are the helper's own arguments; the caller prefixes the interpreter
// and the helper path, which `helperArgv()` does. Every value is a separate
// argv member: no joining, no quoting, no shell (hard requirement 9). User
// mpv tokens travel as repeated `--mpv-arg TOKEN` so argparse can never
// swallow an option-looking token and no token is ever split or merged.

function helperArgv(helperPath, args) {
  return ["python3", str(helperPath)].concat(asList(args))
}

// D-ID-1. The two playlist invocations differ by ONE argument and the
// difference decides whether a user's favourites are rewritten. Building both
// here rather than inline in Service.qml is the point: nothing could see that
// argv before, so nothing could assert it, and the review that caught the
// missing flag caught it by reading rather than by a test.
//
// `--state-dir` is what makes the one-time id remap run, and the helper
// touches no state file without it. So the ACTIVE fetch carries it -- that is
// the one moment we know the user means this list -- and the PROBE must not,
// because a probe runs for every source add, edit, switch and re-check,
// including ones the user then cancels. Remapping global favourites against a
// playlist that never became active would be a loss caused by a fix.
//
// D-SINK-8. Neither builder carries the URL any more, and there is no url
// parameter left on either signature: a parameter nobody reads is a trap. A
// playlist URL carries the provider's credentials, and an argv item sits in
// /proc/<pid>/cmdline -- world-readable -- for as long as the fetch runs. The
// URL travels in the helper's environment instead (fetchEnvironment below),
// which /proc exposes only to the owner. The helper fetches with urllib and
// starts no child in its fetch verbs (it forks mpv only in `player start`,
// on a Process that never receives this environment), so moving the URL
// off argv closes the command-line exposure entirely.
function playlistFetchArgv(helperPath, cacheDir, stateDir) {
  var args = ["playlist", "--cache-dir", str(cacheDir)]
  if (str(stateDir) !== "") args = args.concat(["--state-dir", str(stateDir)])
  return helperArgv(helperPath, args)
}

// D-SINK-19 round 14, R24e (D-SRC-27). The state directory the ACTIVE fetch
// hands the helper, which is what lets its D-ID-1 remap rewrite state.json:
// "" -- the flag omitted, so the helper touches no state file -- while the
// service is in the no-write mode (`blocked`, its stateWriteBlocked reason).
// The mode was enforced in saveState and writeOwnedEntry, and the remap is a
// SECOND writer of the same file, gated only by its own read: in a session
// blocked as init-timeout or absent-unconfirmed over a file that later read
// valid, an active-source fetch could still rename it. "will write nothing
// to it this session" is now true of every writer the service starts.
function fetchStateDir(stateDir, blocked) {
  return str(blocked) !== "" ? "" : str(stateDir)
}

function playlistProbeArgv(helperPath, cacheDir) {
  return helperArgv(helperPath, ["playlist", "--cache-dir", str(cacheDir)])
}

// The EPG helper run has two shapes. A fetch, whose URL reaches the helper
// through the environment exactly as the playlist's does (D-SINK-8), and
// `--now-only`, which recomputes now/next from the cached programme window
// and contacts nobody. Built here rather than inline in Service.qml for the
// reason the playlist builders were (D-ID-1): an argv nothing can see is an
// argv nothing can assert.
function epgFetchArgv(helperPath, cacheDir, nowOnly) {
  var args = ["epg"]
  if (nowOnly) args.push("--now-only")
  return helperArgv(helperPath, args.concat(["--cache-dir", str(cacheDir)]))
}

// D-SINK-8. The environment the three URL-carrying helper spawns run with:
// the playlist fetch, the EPG fetch and the source probe. The helper reads
// OMARCHY_IPTV_URL when `--url` is absent; `--url` stays for a human running
// the helper by hand in their own shell. Empty, null and undefined all give
// {} -- a key present with the string "undefined" would be a fetch of a URL
// nobody typed.
//
// How Quickshell's Process.environment behaves, measured on Quickshell 0.3.1
// / Qt 6.11 rather than read from the docs, because each fact below decides
// whether this is a fix or a new leak:
//   1. It MERGES with the inherited environment. PATH and HOME survive, so
//      the helper still finds python3 and its XDG directories.
//   2. Re-assigning it on the same Process object REPLACES the previous
//      value. A run that assigns {} runs with no URL at all, so a stale URL
//      from the last fetch cannot ride into the `--now-only` run or into a
//      probe of a different source.
//   3. A null value UNSETS an inherited variable, so this function never
//      emits one: the key is either a non-empty string or absent.
// Service.qml assigns it immediately before `running = true`, every time.
var FETCH_URL_ENV = "OMARCHY_IPTV_URL"

function fetchEnvironment(url) {
  var env = {}
  var u = str(url)
  if (u !== "") env[FETCH_URL_ENV] = u
  return env
}

// M2-04. The fetch the consent screen authorizes, and the only place logos
// are downloaded. `--fetch` is what turns the helper's default survey into a
// download, so a command built without it contacts nobody -- the opt-in is
// spelled twice, once in the setting and once here.
// The dead-channel mark, written by the helper so the file lands 0600 inside
// the 0700 source directory -- the same reason logo writes go through it.
// argv items, never shell text: a channel id is playlist-derived.
function failedArgv(helperPath, action, id, cacheDir) {
  var verb = str(action) === "clear" ? "clear" : "mark"
  return helperArgv(helperPath, ["failed", verb, "--id", str(id), "--cache-dir", str(cacheDir)])
}

function logoFetchArgv(helperPath, cacheDir) {
  return helperArgv(helperPath, ["logos", "--fetch", "--cache-dir", str(cacheDir)])
}

// ---- M3-02: audio and subtitle tracks
//
// `player tracks` lists; with a selection it selects FIRST and then lists,
// so one reply carries the player's answer to the request (PLAN-M3
// decision 5). `select` is { type: "audio" | "sub", id: <mpv id> | "no" }
// or absent for a plain list. Anything else is a plain list: a malformed
// selection must not become an argv the helper rejects on the socket's
// behalf.
function playerTracksArgv(socket, select) {
  var argv = ["player", "tracks", "--socket", str(socket)]
  var sel = select || null
  if (sel && (sel.type === "audio" || sel.type === "sub")) {
    var id = trackChoice(sel.id)
    if (id !== "") argv.push(sel.type === "audio" ? "--audio" : "--sub", id)
  }
  return argv
}

// "no" or a non-negative integer as text; "" for anything else.
function trackChoice(id) {
  if (id === "no") return "no"
  var n = Number(id)
  if (typeof id === "boolean" || id === null || id === undefined || id === "" || !isFinite(n) || n < 0 || Math.floor(n) !== n) return ""
  return String(n)
}

// The helper already whitelists and redacts (rule 5); this is the second
// sink guard, because the rows reach guide text and an accessible name.
function parseTracks(status) {
  var list = status && Array.isArray(status.tracks) ? status.tracks : []
  var out = []
  for (var i = 0; i < list.length; i++) {
    var t = list[i]
    if (!t || typeof t !== "object") continue
    if (t.type !== "audio" && t.type !== "sub") continue
    var id = Number(t.id)
    if (typeof t.id === "boolean" || !isFinite(id) || Math.floor(id) !== id) continue
    out.push({
      id: id, type: t.type, selected: t.selected === true,
      // Every free-text field mpv takes from the file goes through the same
      // guard, not just the one that was thought of first: the helper
      // redacts these and this is the second pass, because they reach guide
      // text and an accessible name (rule 5).
      lang: scrubUrls(str(t.lang)), title: scrubUrls(str(t.title)), codec: scrubUrls(str(t.codec)),
      dflt: t["default"] === true, forced: t.forced === true, external: t.external === true
    })
  }
  return out
}

// ISO 639-2/B and -2/T codes mpv reports for the languages an IPTV list
// carries in practice. Anything else shows as the code in upper case,
// which is still more than the player's own OSD gives.
var LANG_NAMES = {
  eng: "English", spa: "Spanish", fra: "French", fre: "French", deu: "German", ger: "German",
  ita: "Italian", por: "Portuguese", nld: "Dutch", dut: "Dutch", rus: "Russian", pol: "Polish",
  tur: "Turkish", ara: "Arabic", hin: "Hindi", urd: "Urdu", ben: "Bengali", tam: "Tamil",
  swe: "Swedish", nor: "Norwegian", dan: "Danish", fin: "Finnish", ell: "Greek", gre: "Greek",
  heb: "Hebrew", jpn: "Japanese", kor: "Korean", zho: "Chinese", chi: "Chinese", tha: "Thai",
  vie: "Vietnamese", ind: "Indonesian", msa: "Malay", may: "Malay", fas: "Persian", per: "Persian",
  ukr: "Ukrainian", ces: "Czech", cze: "Czech", hun: "Hungarian", ron: "Romanian", rum: "Romanian",
  bul: "Bulgarian", srp: "Serbian", hrv: "Croatian", slv: "Slovenian", slk: "Slovak", slo: "Slovak",
  cat: "Catalan", eus: "Basque", baq: "Basque", glg: "Galician", lat: "Latin", mul: "Multiple",
  und: "", zxx: ""
}

function trackLanguage(code) {
  var key = str(code).toLowerCase().trim()
  if (key === "") return ""
  if (LANG_NAMES.hasOwnProperty(key)) return LANG_NAMES[key]
  return key.toUpperCase()
}

// What a row says. The title wins when the stream author wrote one, then
// the language, then the id -- and the id is always there in the detail,
// because two "English" rows with nothing to tell them apart is the common
// case on a provider list.
function trackLabel(t) {
  var title = cleanName(t.title)
  if (title !== "") return title
  var lang = trackLanguage(t.lang)
  if (lang !== "") return lang
  return "Track " + t.id
}

function trackDetail(t) {
  var parts = []
  var lang = trackLanguage(t.lang)
  if (cleanName(t.title) !== "" && lang !== "") parts.push(lang)
  if (str(t.codec) !== "") parts.push(str(t.codec))
  if (t.forced === true) parts.push("forced")
  if (t.external === true) parts.push("external")
  return parts.join(SEP)
}

// The picker's rows: a header per kind, the tracks under it, an `Off` row
// for subtitles that is selected when no subtitle is. A kind with nothing
// reported shows a row saying so, because an empty section reads as a
// picker that failed to load.
function trackRows(tracks) {
  var list = asList(tracks)
  var out = []
  var kinds = [["audio", "Audio"], ["sub", "Subtitles"]]
  for (var k = 0; k < kinds.length; k++) {
    var type = kinds[k][0]
    out.push({ kind: "header", type: type, label: kinds[k][1], detail: "", id: 0, selected: false })
    var any = false
    var anySelected = false
    if (type === "sub") {
      for (var j = 0; j < list.length; j++) if (list[j].type === "sub" && list[j].selected === true) anySelected = true
      out.push({ kind: "track", type: "sub", id: "no", label: "Off", detail: "", selected: !anySelected })
    }
    for (var i = 0; i < list.length; i++) {
      var t = list[i]
      if (t.type !== type) continue
      any = true
      out.push({ kind: "track", type: type, id: t.id, label: trackLabel(t), detail: trackDetail(t), selected: t.selected === true })
    }
    if (!any && type === "audio") out.push({ kind: "empty", type: type, label: "None reported", detail: "", id: 0, selected: false })
  }
  return out
}

// Where the cursor opens: the selected audio track, else the first row
// that can be chosen. -1 when nothing can.
function trackCursorHome(rows) {
  var list = asList(rows)
  var first = -1
  for (var i = 0; i < list.length; i++) {
    if (list[i].kind !== "track") continue
    if (first === -1) first = i
    if (list[i].type === "audio" && list[i].selected === true) return i
  }
  return first
}

// j/k over the rows: headers and empty rows are stepped over, the ends
// wrap, like the group column (moveScope).
function moveTrackCursor(rows, index, delta) {
  var list = asList(rows)
  var at = []
  for (var i = 0; i < list.length; i++) if (list[i].kind === "track") at.push(i)
  if (at.length === 0) return -1
  var from = Math.floor(Number(index))
  var cur = at.indexOf(from)
  if (cur === -1) {
    // Not on a choosable row (a header, or nowhere yet): the nearest one in
    // the direction asked, wrapping -- so -1 with +1 is the first row and
    // -1 with -1 is the last, which is what Home and End send.
    if (delta < 0) { for (var d = at.length - 1; d >= 0; d--) if (at[d] < from) return at[d]; return at[at.length - 1] }
    for (var u = 0; u < at.length; u++) if (at[u] > from) return at[u]
    return at[0]
  }
  var step = delta < 0 ? -1 : 1
  return at[(cur + step + at.length) % at.length]
}

// Whether an open picker should ask the player about the channel that is
// playing now. Pure, and in the model rather than inline in the service,
// because the inline version was a self-sustaining loop and no test in the
// suite could reach it (rule 12).
//
// THE LOOP, which shipped past two preflights and a green gate: the gate was
// "the rows do not describe the playing channel", and the one reply that
// cannot satisfy it -- `running: false`, which the helper emits whenever the
// socket does not answer -- is the reply that CLEARS the stamp. So the gate
// re-armed itself on its own reply: ask, no player, clear, ask, at about six
// helper spawns a second, with the health poll starved behind a permanently
// busy control channel.
//
// `askedFor` is what breaks it: the channel the last ask was ISSUED for.
// It is cleared when the playing channel changes, when the picker closes,
// and when a health status shows the player alive -- that third one is the
// recovery edge, added a pass later, and it is why the `rowsFor` guard
// below is load-bearing rather than the belt-and-braces an earlier version
// of this comment called it. So: at most one automatic ask per channel per
// observed-alive edge, not "once per channel" flat. An explicit ask
// (opening the picker, choosing a track) does not come through here.
// How many times one channel may be re-asked after an observed-alive edge
// before the picker stops trying. Two, because the case it exists for is a
// player that came up between the ask and the answer -- one retry covers
// that, a second covers a slow first load, and a third only repeats.
var TRACKS_RECOVERY_MAX = 2

function shouldRefreshTracks(opts) {
  var o = opts || {}
  var playing = str(o.playingId)
  if (o.wanted !== true || playing === "") return false
  // D-TRK-8, which was an ACCEPTED residual until it was asked to be fixed:
  // a healthy player that never answers gave one ask every two health ticks
  // for ever, with the caption alternating on that cadence. The COUNTER
  // lives in the service (`tracksRecoveries`), because only the service sees
  // the replies; the CAP and this comparison live here so a test can reach
  // the decision. An earlier version of this comment claimed the bound
  // avoided new service state, which it does not -- it adds a counter and a
  // fifth input to this function. What it avoids is another gate spelled out
  // in QML, which is how both of this release's P1s got past the suite.
  if (Math.floor(Number(o.recoveries) || 0) >= TRACKS_RECOVERY_MAX) return false
  // LOAD-BEARING, and the comment that stood here said the opposite. It
  // argued that every path setting `rowsFor` goes through requestTracks,
  // which sets `askedFor` first, so this line could refuse nothing the one
  // below would not -- true when it was written, and made false one pass
  // later by the recovery edge, which clears `askedFor` and leaves
  // `rowsFor` alone. In that state this is the only refusal, and without it
  // an open picker over a healthy player asks again every second health
  // tick, for ever. The old comment also predicted, correctly, that the
  // suite stayed green without the line -- so it pre-authorised deleting a
  // line that had become the bound. The case below now asserts it.
  if (str(o.rowsFor) === playing) return false
  return str(o.askedFor) !== playing
}

// The one line under the title. `state` is the service's tracksState.
function trackPanelMessage(state, rows) {
  var st = str(state)
  if (st === "asking") return "Asking the player" + ELLIPSIS
  if (st === "failed") return "The player did not answer"
  if (st === "idle") return "Nothing is playing"
  return ""
}

// UX 7.1: what a row is called on the bus. Position is over the choosable
// rows, not the drawn ones, because a header is not a choice.
function trackAccessibleName(rows, index) {
  var list = asList(rows)
  var row = list[index]
  if (!row) return ""
  if (row.kind !== "track") return str(row.label)
  var n = 0, pos = 0
  for (var i = 0; i < list.length; i++) {
    if (list[i].kind !== "track") continue
    n++
    if (i === index) pos = n
  }
  var parts = [str(row.label)]
  if (str(row.detail) !== "") parts.push(str(row.detail).split(SEP).join(", "))
  parts.push(row.type === "audio" ? "audio" : "subtitles")
  if (row.selected === true) parts.push("selected")
  parts.push(pos + " of " + n)
  return parts.join(", ")
}
export {
  MPV_HANDOFF, MPV_HANDOFF_SCRIPT_OPTS, MPV_YTDL_OFF, MPV_HANDOFF_TEXT,
  MPV_DISK_WARN, MPV_DISK_TEXT, mpvOptionBase, mpvHandoffName, mpvDiskName,
  mpvArgWarning, mpvArgWarnings, MPV_REFUSED_TEXT, MPV_REFUSED_JUNK_TEXT,
  mpvRefusedWarning, mpvRefusedWarnings, splitMpvArgs, demuxerNamesTls,
  mpvRejectedLine, mpvRejectedName, headerArgs, MPV_RAW_PREFIX,
  mpvWindowTitle, playerDirs, dirnameOf, buildMpvArgv, mpvPinBlock,
  helperArgv, playlistFetchArgv, fetchStateDir, playlistProbeArgv,
  epgFetchArgv, FETCH_URL_ENV, fetchEnvironment, failedArgv, logoFetchArgv,
  playerTracksArgv, trackChoice, parseTracks, LANG_NAMES, trackLanguage,
  trackLabel, trackDetail, trackRows, trackCursorHome, moveTrackCursor,
  TRACKS_RECOVERY_MAX, shouldRefreshTracks, trackPanelMessage,
  trackAccessibleName
}
